def gift (need give : U → Nat) (w : List U) (z : Nat) : Nat := total w fun u => cond (decide (need u ≤ z)) (give u) 0
def level (need : U → Nat) (giving : Nat → Nat) (use give : U → Nat) (w : List U) (x : Nat) : Nat := RegimeMargin.step giving (taken use w) x + gift need give w (x - taken use w)
abbrev step need kids giving use give := TurningInTime.pair (after need kids) (level need giving use give)
def net need kids giving use give := Law.stepWhile (Goes need) (step need kids giving use give)
abbrev course need kids giving use give s := Law.orbit (step need kids giving use give) s
